CREATE OR REPLACE FUNCTION public.pm_quote_payment_date(_quote uuid,_start date,_value date,_manual boolean) RETURNS date LANGUAGE sql STABLE SET search_path=public AS $$ SELECT CASE WHEN _value IS NULL OR coalesce(_manual,false) THEN _value ELSE pm_calendar_shift(_start,pm_relative_offset(_value)-pm_relative_offset(coalesce((SELECT min((s->>'start_date')::date) FROM quote_relative_schedules r CROSS JOIN LATERAL jsonb_array_elements(r.original_dates->'stages') s WHERE r.quote_id=_quote),(SELECT min(start_date) FROM quote_stages WHERE quote_id=_quote),date '2000-01-03'))) END $$;